kl = Kinloom()

# --- stand-in for the game ---
quest = {
    "title": "The Glowcap Grove",
    "text": "Deep in the cave, the Glowcaps have gone dark. Bring three back to the herbalist before nightfall.",
}

def show_text(text):
    print(text)

# --- read the quest aloud ---
audio = kl.speak("NARRATOR", quest["text"])
show_text(quest["text"])
if audio is not None:
    play(audio.path)  # game's own audio player
